/* Types */
export type Applied = {
	created: number,
	warnings: string[],
};

/**
 *  The issue and sub-issues a template created. `skipped` names references the template
 *  no longer resolves (a deleted label, project or status); those fields were left unset.
 */
export type AppliedTemplate = {
	issue: Issue,
	sub_issues: Issue[],
	skipped: string[],
};

/**  A stored image; its bytes come from `attachments::get`. */
export type Attachment = {
	id: AttachmentId,
	sha256: string,
	mime: string,
	bytes: number,
	created_at: string,
};

/**  An image's bytes and type, as `attachments_get` returns them. */
export type AttachmentData = {
	mime: string,
	bytes: number[],
};

export type AttachmentId = number;

export type Bar = {
	issue_id: IssueId,
	start: string,
	end: string,
	from_estimate: boolean,
};

/**
 *  `time` is approximate: whole days, from creation to finish, whose end found an unfinished blocker linked.
 *  `avg_days` spreads it over every issue finished in the range.
 */
export type Blocked = {
	now: BlockedItem[],
	time: BlockedTime[],
	avg_days: number | null,
};

/**  An open issue with an unfinished `blocks` blocker; `days` since the newest such link began. */
export type BlockedItem = {
	issue_id: IssueId,
	key: string,
	title: string,
	blocked_by: string[],
	days: number | null,
};

export type BlockedTime = {
	issue_id: IssueId,
	key: string,
	title: string,
	days: number | null,
};

export type Bucket = "Day" | "Week" | "Month";

/**  One edit for a whole selection: the patch, labels to add or remove, and a relation from each issue to `add_relation.1`. */
export type BulkPatch = {
	patch?: IssuePatch,
	add_labels?: LabelId[],
	remove_labels?: LabelId[],
	add_relation?: [RelationKind, IssueId] | null,
	/**  `Some(true)` archives, `Some(false)` restores. */
	archive?: boolean | null,
};

/**  One row of change history. */
export type Change = {
	id: number,
	at: string,
	source: ChangeSource,
	entity: string,
	entity_id: string,
	field: string,
	old_value: Value | null,
	new_value: Value | null,
};

export type ChangeSource = "Ui" | "Agent" | "Cli" | "RemindersImport" | "Migration" | "System" | "Undo" | "Redo";

export type Comment = {
	id: CommentId,
	issue_id: IssueId,
	body: string,
	created_at: string,
	updated_at: string,
};

export type CommentId = number;

export type Cycle = {
	id: CycleId,
	number: number,
	name: string | null,
	start_date: string,
	end_date: string,
	icon: string | null,
	color: string | null,
	/**  The retrospective: a one-sentence goal, whether it was met (`None` until decided), a 1 to 5 rating, notes. */
	goal?: string | null,
	goal_met?: boolean | null,
	rating?: number | null,
	notes?: string,
};

/**
 *  A cycle's commitment: its members at the end of its start day against what it holds and finished by its end
 *  (or today, for a cycle still running). Percentages are `None` when nothing was committed.
 */
export type CycleCommit = {
	committed: number,
	committed_points: number | null,
	/**  Committed issues finished. */
	done: number,
	done_points: number | null,
	say_do_pct: number | null,
	say_do_points_pct: number | null,
	/**  Issues that joined or left the cycle after its start day. */
	added: number,
	added_points: number | null,
	removed: number,
	removed_points: number | null,
	/**  (added + removed) as a percentage of what was committed. */
	scope_change_pct: number | null,
	scope_change_points_pct: number | null,
};

export type CycleId = number;

export type CycleTime = {
	p50_days: number | null,
	p85_days: number | null,
	n: number,
	points: CycleTimePoint[],
};

export type CycleTimePoint = {
	issue_id: IssueId,
	key: string,
	title: string,
	completed: string,
	days: number | null,
};

/**  A question for the owner. `answer` is an option key, or free text when the options did not fit. */
export type Decision = {
	id: DecisionId,
	question: string,
	context: string,
	options: DecisionOption[],
	recommendation: string | null,
	mode: DecisionMode,
	status: DecisionStatus,
	answer: string | null,
	note: string,
	source: string,
	external_id: string | null,
	created_at: string,
	answered_at: string | null,
	issue_ids: IssueId[],
};

export type DecisionId = number;

/**  What create takes. `source` defaults to the caller's own (`cli`, `ui`). */
export type DecisionInput = {
	question: string,
	context?: string,
	options?: DecisionOption[],
	recommendation: string | null,
	mode: DecisionMode,
	source: string | null,
	external_id: string | null,
	issue_ids?: IssueId[],
};

export type DecisionMode = 
/**  Whoever raised it waits for the answer. */
"blocking" | 
/**  Whoever raised it carries on with its recommendation. */
"assume";

/**  One choice of a [`Decision`]; `key` is what an answer and the recommendation name. */
export type DecisionOption = {
	key: string,
	label: string,
	tradeoff?: string,
};

export type DecisionStatus = "open" | "answered" | "withdrawn";

export type Density = "comfortable" | "compact";

export type Due = ({ Date: string }) & { DateTime?: never } | 
/**  `tz` is an IANA name. */
({ DateTime: {
	utc: string,
	tz: string,
} }) & { Date?: never };

/**  What crosses the Tauri and HTTP boundary. */
export type ErrorPayload = {
	kind: string,
	message: string,
};

/**  Times are local wall-clock (no zone); an all-day event keeps midnight and the UI ignores the time. */
export type Event = {
	id: EventId,
	title: string,
	starts_at: string,
	ends_at: string | null,
	all_day: boolean,
	place: string | null,
	notes: string,
	icon: string | null,
	color: string | null,
	archived: boolean,
	issue_ids: IssueId[],
};

export type EventId = number;

/**  What create and update take: everything on [`Event`] except the id and the links. */
export type EventInput = {
	title: string,
	starts_at: string,
	ends_at: string | null,
	all_day: boolean,
	place: string | null,
	notes: string,
	icon: string | null,
	color: string | null,
	archived: boolean,
};

export type FieldRef = ({ Fixed: FixedField }) & { Property?: never } | ({ Property: string }) & { Fixed?: never };

export type Filter = ({ And: Filter[] }) & { Cond?: never; Not?: never; Or?: never } | ({ Or: Filter[] }) & { And?: never; Cond?: never; Not?: never } | ({ Not: Filter }) & { And?: never; Cond?: never; Or?: never } | ({ Cond: {
	field: FieldRef,
	op: Op,
	value: Value,
} }) & { And?: never; Not?: never; Or?: never };

export type FixedField = "Title" | "Status" | "StatusCategory" | "Priority" | "Project" | "Milestone" | "Cycle" | "Label" | "Parent" | "StartDate" | "DueDate" | "Estimate" | "Points" | "CreatedAt" | "UpdatedAt" | "CompletedAt" | "Archived" | "Key" | "SubIssueProgress" | "RelationCount" | "CommentCount" | 
/**  Shows `done/total` of the description's task lines; not sortable or filterable. */
"Checklist" | 
/**  Filter only: the issue has a relation of the given kind id(s), on either end. */
"RelationKind" | 
/**  An issue's project status; on a project view, use `Status`. */
"ProjectStatus" | 
/**  Project views only. */
"TargetDate" | 
/**  Project views only: the percent of the project's issues that are completed. */
"Progress" | 
/**  Project views only: the project's issues, archived ones left out. */
"IssueCount" | 
/**  Project views only: shows progress as a percent with a scope and completed sparkline; sorts and filters as `Progress`. */
"ProgressChart";

/**
 *  Active-kind days over cycle-time days, per finished issue that has a cycle time above zero (`n` of them).
 *  `distribution` counts them in five 20% bins, lowest first.
 */
export type FlowEfficiency = {
	avg_pct: number | null,
	n: number,
	distribution: number[],
	waiting: WaitingStatus[],
};

/**  Whether time in a status is work (`Active`), blocked on someone or something (`Waiting`) or neither (`Idle`). */
export type FlowKind = "Active" | "Waiting" | "Idle";

/**  The sidebar section a folder belongs to; its items live in the table of the same name. */
export type FolderSection = "pin" | "view" | "project" | "cycle";

/**
 *  When the open issues are likely done at the recent pace. `p50` and `p85` are the days by which half and
 *  85 in 100 simulated futures are finished; both are `None` when `enough` is false (too little history) or
 *  nothing is open. `completions` is what finished in the `window_days` before today.
 */
export type Forecast = {
	open: number,
	completions: number,
	window_days: number,
	enough: boolean,
	p50: string | null,
	p85: string | null,
};

/**  What to forecast: the issues the filter lets through, or one cycle's own members. */
export type ForecastQuery = {
	filter: Filter | null,
	cycle: CycleId | null,
};

/**
 *  Everything an import would create. The lists of statuses, labels, projects, cycles and property
 *  definitions hold only what does not exist yet.
 */
export type ImportPlan = {
	source?: string,
	statuses?: PlanStatus[],
	labels?: string[],
	projects?: string[],
	cycles?: PlanCycle[],
	property_defs?: PropertyDef[],
	issues?: PlanIssue[],
	relations?: PlanRelation[],
	warnings?: string[],
	skipped?: Skipped[],
	/**  Source columns no field was mapped to. */
	unmapped?: string[],
};

export type Issue = {
	id: IssueId,
	key: string,
	title: string,
	description: string,
	status_id: StatusId,
	priority: number,
	project_id: ProjectId | null,
	milestone_id: MilestoneId | null,
	parent_id: IssueId | null,
	cycle_id: CycleId | null,
	label_ids: LabelId[],
	start_date: string | null,
	due: Due | null,
	estimate_minutes: number | null,
	/**  At least 0, one decimal at most (checked on write). */
	points: number | null,
	properties: { [key in string]: Value },
	created_at: string,
	updated_at: string,
	completed_at: string | null,
	archived_at: string | null,
};

export type IssueId = number;

/**  `None` leaves a field alone; for nullable fields `Some(None)` clears it. */
export type IssuePatch = {
	title?: string | null,
	description?: string | null,
	status_id?: StatusId | null,
	priority?: number | null,
	project_id?: ProjectId | null,
	milestone_id?: MilestoneId | null,
	parent_id?: IssueId | null,
	cycle_id?: CycleId | null,
	label_ids?: LabelId[] | null,
	start_date?: string | null,
	due?: Due | null,
	estimate_minutes?: number | null,
	points?: number | null,
	properties?: { [key in string]: Value } | null,
};

/**  The counts a view can display that an issue row does not carry. */
export type IssueStats = {
	issue_id: IssueId,
	sub_total: number,
	sub_done: number,
	relations: number,
	comments: number,
};

export type IssueTemplate = {
	id: TemplateId,
	name: string,
	slug: string,
	icon: string | null,
	color: string | null,
	body: TemplateBody,
};

export type Label = {
	id: LabelId,
	name: string,
	/**  A palette key. */
	color: string,
	/**  The reference hex for `color`, for showing it without the palette. */
	color_hex: string,
	icon: string | null,
};

export type LabelBreakdown = {
	label_id: number | null,
	name: string,
	completed: number,
	points: number | null,
};

export type LabelId = number;

export type Layout = "List" | "Table" | "Board" | "Gantt" | "Calendar";

/**  Calendar days in the workspace zone, nearest-rank percentiles; `None` without a finished issue. */
export type LeadTime = {
	p50_days: number | null,
	p85_days: number | null,
	n: number,
};

/**  What is summed: story points, issue count, or estimated time (minutes). */
export type Measure = "points" | "count" | "time";

export type Metrics = {
	from: string,
	to: string,
	bucket: Bucket,
	buckets: MetricsBucket[],
	lead_time: LeadTime,
	cycle_time: CycleTime,
	wip_now: number,
	by_label: LabelBreakdown[],
	by_source: SourceBreakdown[],
	/**  The last six finished cycles. */
	velocity: VelocityCycle[],
	/**  Fewer than five issues finished in the range: read the numbers as anecdotes. */
	thin: boolean,
	/**  Present for a cycle scope only. */
	cycle?: CycleCommit | null,
	blocked?: Blocked | null,
	flow?: FlowEfficiency | null,
};

/**  One bucket; `scope` is open plus finished-in-range work at the bucket's end, `done_total` the finished part. */
export type MetricsBucket = {
	start: string,
	created: number,
	completed: number,
	completed_points: number | null,
	scope: number,
	done_total: number,
	wip: number,
};

/**  `measure` is `count` or `points` (time is refused); it picks what the label breakdown ranks by. */
export type MetricsQuery = {
	scope: MetricsScope,
	bucket: Bucket,
	filter: Filter | null,
	measure: Measure,
};

/**  What the metrics cover: a run of days, or one cycle's own dates. */
export type MetricsScope = ({ Range: {
	from: string,
	to: string,
} }) & { Cycle?: never } | ({ Cycle: CycleId }) & { Range?: never };

export type Milestone = {
	id: MilestoneId,
	project_id: ProjectId,
	name: string,
	target_date: string | null,
};

export type MilestoneId = number;

/**  Everything but `title` is optional; `created_at` and `completed_at` exist for migrations. */
export type NewIssue = {
	title?: string,
	description?: string | null,
	status_id?: StatusId | null,
	priority?: number | null,
	project_id?: ProjectId | null,
	milestone_id?: MilestoneId | null,
	parent_id?: IssueId | null,
	cycle_id?: CycleId | null,
	label_ids?: LabelId[] | null,
	start_date?: string | null,
	due?: Due | null,
	estimate_minutes?: number | null,
	points?: number | null,
	properties?: { [key in string]: Value } | null,
	created_at?: string | null,
	completed_at?: string | null,
};

export type Op = "Eq" | "Neq" | "In" | "NotIn" | "Lt" | "Lte" | "Gt" | "Gte" | "Contains" | "IsEmpty" | "IsNotEmpty";

export type ParsedQuickAdd = {
	title: string,
	due: Due | null,
	start_date: string | null,
	priority: number | null,
	project_slug: string | null,
	label_names: string[],
	estimate_minutes: number | null,
	points: number | null,
};

export type Pin = {
	id: PinId,
	kind: PinKind,
	target: string,
	title: string | null,
	position: number,
};

export type PinId = number;

export type PinKind = "Issue" | "Project" | "View" | "Cycle" | "Note" | "Url" | "Folder";

/**  Where one pin, view, project or cycle sits: the folder (`None` is the section's top level) and its place there. */
export type Placement = {
	section: FolderSection,
	id: number,
	folder_id: ViewFolderId | null,
	position: number,
};

export type PlanCycle = {
	name: string | null,
	start_date: string,
	end_date: string,
};

/**
 *  Names refer to statuses, labels and projects; a cycle is its start date (cycles never overlap);
 *  `parent` and relation ends are source identifiers.
 */
export type PlanIssue = {
	external_id: string,
	title: string,
	description: string,
	status: string | null,
	priority: number,
	project: string | null,
	labels: string[],
	start_date: string | null,
	due_date: string | null,
	estimate_minutes: number | null,
	points?: number | null,
	properties: { [key in string]: Value },
	parent: string | null,
	cycle: string | null,
};

export type PlanRelation = {
	from: string,
	to: string,
	kind: RelationKind,
};

export type PlanStatus = {
	name: string,
	category: StatusCategory,
};

/**  The totals at the end of one local day. */
export type ProgressDay = {
	date: string,
	/**  Every issue that existed and is not canceled. */
	scope: number | null,
	/**  Those whose status category is started or completed. */
	started: number | null,
	completed: number | null,
};

/**  What a progress chart is about: the issues of a project or cycle, or those a saved view shows now. */
export type ProgressScope = ({ Project: ProjectId }) & { Cycle?: never; View?: never } | ({ Cycle: CycleId }) & { Project?: never; View?: never } | ({ View: ViewId }) & { Cycle?: never; Project?: never };

export type ProgressSeries = {
	days: ProgressDay[],
	measure: Measure,
	from: string,
	to: string,
};

export type Project = {
	id: ProjectId,
	slug: string,
	name: string,
	description: string | null,
	doc_link: string | null,
	start_date: string | null,
	target_date: string | null,
	archived_at: string | null,
	/**  Set by the database; an update ignores what the caller sends. */
	created_at: string,
	updated_at: string,
	icon: string | null,
	color: string | null,
	status_id: ProjectStatusId,
	/**  The issue scale: 0 none, 1 urgent, 2 high, 3 medium, 4 low. */
	priority: number,
	label_ids: LabelId[],
	properties: { [key in string]: Value },
};

export type ProjectId = number;

/**  A project as a project view lists it, with its issue counts (archived issues left out). */
export type ProjectRow = {
	project: Project,
	issue_total: number,
	issue_done: number,
};

export type ProjectStatus = {
	id: ProjectStatusId,
	name: string,
	category: ProjectStatusCategory,
	position: number,
	/**  A palette key. */
	color: string,
	/**  The reference hex for `color`, for showing it without the palette. */
	color_hex: string,
	icon: string | null,
};

export type ProjectStatusCategory = "Planned" | "Started" | "Paused" | "Completed" | "Cancelled";

export type ProjectStatusId = number;

/**  Which entities a custom property applies to. */
export type PropertyAppliesTo = "Issues" | "Projects" | "Both";

export type PropertyDef = {
	key: string,
	name: string,
	kind: PropertyKind,
	options: SelectOption[],
	/**  Limits the issue side to one project; never set for a projects-only property. */
	project_id: ProjectId | null,
	position: number,
	applies_to?: PropertyAppliesTo,
};

export type PropertyKind = "Text" | "Number" | "Date" | "Select" | "MultiSelect" | "Checkbox" | "Url" | "NoteLink";

export type Relation = {
	from: IssueId,
	to: IssueId,
	kind: RelationKind,
};

/**  The id of a row in `relation_kinds`: "blocks", "related", "duplicate", or any other kind's slug. */
export type RelationKind = string;

/**  A kind of relation: `forward` reads from the `from` issue ("blocks"), `reverse` from the `to` issue ("blocked by"). */
export type RelationKindDef = {
	id: RelationKind,
	name: string,
	forward: string,
	reverse: string,
	symmetric: boolean,
	built_in: boolean,
	position: number,
};

export type Reschedule = {
	issue_id: IssueId,
	start_date: string,
	due_date: string,
};

export type ResolvedPin = {
	pin: Pin,
	label: string,
	archived: boolean,
	/**  A UI route, or the external URL. */
	route: string,
};

export type SavedView = {
	id: ViewId,
	name: string,
	entity: ViewEntity,
	def: ViewDef,
	position: number,
	icon: string | null,
	color: string | null,
	/**  The template the view was made from, for "Reset to template". */
	template_id: ViewTemplateId | null,
	/**  The sidebar folder the view sits in; `None` is the top level. */
	folder_id: ViewFolderId | null,
};

export type SelectOption = {
	value: string,
	color: string,
};

/**  A source row that will not be imported. `row` counts from 1 (CSV: the header is row 1). */
export type Skipped = {
	row: number,
	reason: string,
};

export type Sort = {
	field: FieldRef,
	descending: boolean,
};

/**  `source` is a [`ChangeSource`] name: Ui, Cli, Agent, Migration and so on. */
export type SourceBreakdown = {
	source: string,
	created: number,
	completed: number,
};

/**  An issue past its status's nudge age: where it sits, since when, and for how many whole days. */
export type StaleIssue = {
	issue: Issue,
	status_name: string,
	nudge_days: number,
	since: string,
	days: number,
};

export type Status = {
	id: StatusId,
	name: string,
	category: StatusCategory,
	position: number,
	/**  A palette key. */
	color: string,
	/**  The reference hex for `color`, for showing it without the palette. */
	color_hex: string,
	icon: string | null,
	/**  What the status means, in a sentence or two. */
	definition: string,
	/**  How time in this status counts for flow efficiency. */
	flow_kind: FlowKind,
	/**  Issues sitting here this many days are stale (for nudges); none means never. */
	nudge_days: number | null,
};

export type StatusCategory = "Backlog" | "Unstarted" | "Started" | "Completed" | "Canceled";

export type StatusId = number;

export type SubIssue = {
	title?: string,
	fields?: TemplateFields,
};

export type SubIssues = "nest" | "flat" | "hide";

export type SyncState = "Off" | ({ Ok: {
	at: string,
} }) & { Error?: never } | ({ Error: {
	at: string,
	message: string,
} }) & { Ok?: never };

export type SyncStatus = {
	reminders: SyncState,
	gcal: SyncState,
	export: SyncState,
	/**  Absent in statuses saved before backups reported here. */
	backup?: SyncState,
};

/**  Stored as JSON. `title_prefix` is put before the issue's own title. */
export type TemplateBody = {
	title_prefix?: string,
	fields?: TemplateFields,
	sub_issues?: SubIssue[],
};

/**  The fields a template prefills. Each is a default; an override on the issue wins. */
export type TemplateFields = {
	description?: string | null,
	status_id?: StatusId | null,
	priority?: number | null,
	project_id?: ProjectId | null,
	label_ids?: LabelId[],
	estimate_minutes?: number | null,
	points?: number | null,
	properties?: { [key in string]: Value },
};

export type TemplateId = number;

/**  What create and update take: the whole template, replaced on update. */
export type TemplateInput = {
	name: string,
	slug: string,
	icon: string | null,
	color: string | null,
	body: TemplateBody,
};

/**  What undo and redo would do next: the label of the step, or `None` when the stack is empty. */
export type UndoStatus = {
	undo: string | null,
	redo: string | null,
};

export type Value = null | boolean | number | string | Value[] | { [key in string]: Value };

export type VelocityCycle = {
	cycle_id: CycleId,
	name: string,
	points: number | null,
	count: number,
};

/**  Completed in one cycle or week. */
export type VelocityPeriod = {
	start: string,
	end: string,
	label: string,
	completed: number | null,
};

/**
 *  `columns` is the ordered list of displayed fields in every layout; empty means the layout's default.
 *  The display settings default so views stored before they existed still load.
 */
export type ViewDef = {
	filter: Filter | null,
	sorts: Sort[],
	group_by: FieldRef | null,
	layout: Layout,
	columns: FieldRef[],
	include_archived: boolean,
	density?: Density,
	show_empty_groups?: boolean,
	show_sub_issues?: SubIssues,
	/**  The board's card fields; empty means `columns`. */
	card_fields?: FieldRef[],
	show_weekends?: boolean,
	/**  Long titles, labels and values wrap onto more lines instead of being cut off. */
	wrap?: Wrap,
};

/**  What a saved view lists. A project view's fields are project fields. */
export type ViewEntity = "issue" | "project";

/**  A sidebar folder. It holds items of its own section and folders of that section, nested by `parent_id`. */
export type ViewFolder = {
	id: ViewFolderId,
	name: string,
	position: number,
	section: FolderSection,
	parent_id: ViewFolderId | null,
};

export type ViewFolderId = number;

export type ViewId = number;

/**  A saved view definition that new views start from. */
export type ViewTemplate = {
	id: ViewTemplateId,
	name: string,
	icon: string | null,
	color: string | null,
	def: ViewDef,
	position: number,
};

export type ViewTemplateId = number;

/**  Days the finished issues spent in one Waiting status between starting and finishing. */
export type WaitingStatus = {
	status_id: StatusId,
	name: string,
	days: number | null,
	issues: number,
};

export type WorkBlock = {
	id: WorkBlockId,
	issue_id: IssueId,
	start_utc: string,
	end_utc: string,
};

export type WorkBlockId = number;

export type WorkspaceStatus = {
	setup_done: boolean,
	name: string | null,
	key: string,
	timezone: string,
};

export type Wrap = "off" | "on";
